  INSERT INTO monetization_legal_cards(rule_key, status, certainty, payer, beneficiary, billing_event, revenue_nature, contractual_relation, required_document, required_terms, cancellation_policy, refund_policy, tax_notes, invoice_notes, regulatory_notes, legal_basis, source_name, source_url, verified_on, open_questions, note)
  VALUES ('premium.document_preparation', 'yellow', 'medium', 'Organização que propõe projeto', 'A plataforma', 'Documento montado e entregue', 'Receita de prestação de serviço de software, por operação', 'Contrato de adesão aos Termos de Uso', 'Termos aceitos; nota fiscal', 'Termos de Uso, Política de Reembolso, e aviso de que o documento é rascunho sujeito a revisão humana', 'Compra por operação', 'Mesmo ponto do art. 49 do CDC', 'ISS, mesmos itens.', 'Nota por operação, não implementada', 'RISCO PRÓPRIO desta regra: documento gerado com apoio de IA pode ser confundido com peça técnica de responsabilidade profissional. A plataforma já marca a saída como rascunho sujeito a revisão humana e exige aprovação a quatro olhos, mas a fronteira com atividade privativa de profissão regulamentada precisa de parecer.', 'Lei Complementar 116/2003, lista anexa: item 1.03 ''Processamento, armazenamento ou hospedagem de dados, textos, imagens, vídeos, páginas eletrônicas, aplicativos e sistemas de informação, entre outros formatos, e congêneres''; item 1.05 ''Licenciamento ou cessão de direito de uso de programas de computação''; item 1.07 ''Suporte técnico em informática, inclusive instalação, configuração e manutenção de programas de computação e bancos de dados''. STF, ADI 1945 e ADI 5659, julgadas em 18/02/2021: incide ISS, e não ICMS, sobre o licenciamento de software, com modulação de efeitos aprovada em 24/02/2021.', 'Planalto — Lei Complementar 116/2003 (texto literal dos itens) + STF ADI 1945 e 5659', 'https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp116.htm', '2026-10-06', 'Fronteira com atividade privativa de profissão regulamentada (contabilidade, engenharia, advocacia) conforme o tipo de documento. Direito de arrependimento. Responsabilidade por erro no documento gerado.', 'O risco aqui não é tributário: é de responsabilidade técnica pelo conteúdo gerado.')
  RETURNING id, rule_key, status
)
UPDATE monetization_rules r SET legal_card_id = c.id,
       legal_status = CASE WHEN c.status = 'red' THEN 'refused' ELSE 'review_required' END
  FROM c WHERE r.key = c.rule_key;

-- data.territorial_intelligence — carta RED
WITH c AS (
  INSERT INTO monetization_legal_cards(rule_key, status, certainty, payer, beneficiary, billing_event, revenue_nature, contractual_relation, required_document, required_terms, cancellation_policy, refund_policy, tax_notes, invoice_notes, regulatory_notes, legal_basis, source_name, source_url, verified_on, open_questions, note)
  VALUES ('data.territorial_intelligence', 'red', 'medium', 'Órgão público, empresa ou fundação', 'A plataforma', 'Acesso contratado a painel, relatório ou API de inteligência agregada', 'Receita de prestação de serviço de informação', 'Contrato com cláusula específica de uso de dados', 'Contrato; nota fiscal; e registro da base legal do tratamento', 'Termos de uso de dados; e, para órgão público, os termos de contratação administrativa', 'Conforme contrato', 'Conforme contrato', 'Enquadramento depende de ser serviço de informação ou licenciamento de base. Não analisado.', 'Não implementada', 'O risco central é de PRIVACIDADE, não tributário. Dado anonimizado não é dado pessoal (LGPD art. 12), MAS deixa de valer essa regra se a anonimização puder ser revertida com esforços razoáveis — e agregado territorial com pouca contagem é exatamente onde a reidentificação acontece. Vender dado pessoal, ainda que indiretamente identificável, não está autorizado por nenhuma base legal aqui. Também é preciso definir quem é controlador do dado: a organização que o inseriu ou a plataforma.', 'Lei 13.709/2018 (LGPD), art. 5º, III: ''dado anonimizado'' é o dado relativo a titular que não possa ser identificado, considerando a utilização de meios técnicos razoáveis e disponíveis na ocasião de seu tratamento; art. 5º, XI define ''anonimização''. Art. 12: dado anonimizado não é dado pessoal, SALVO quando o processo de anonimização puder ser revertido com esforços razoáveis, considerando custo, tempo e tecnologias disponíveis.', 'Planalto — Lei 13.709/2018, arts. 5º, III e XI, e 12 (texto literal)', 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm', '2026-10-06', 'Limite mínimo de agregação para que a reversão não seja razoável. Quem é controlador. Base legal do tratamento para finalidade de produto. Necessidade de RIPD. Se os contratos com as organizações permitem uso agregado. TODAS exigem DPO e advogado.', 'VERMELHA. É o maior ticket potencial segundo os documentos e o maior risco de privacidade do produto. Nada deve ser construído aqui antes de RIPD e DPO nomeado.')
  RETURNING id, rule_key, status
)
UPDATE monetization_rules r SET legal_card_id = c.id,
       legal_status = CASE WHEN c.status = 'red' THEN 'refused' ELSE 'review_required' END
  FROM c WHERE r.key = c.rule_key;
